def min_moves_to_opposite_parity(n, a):
    # Initialize result list with -1
    result = [-1] * n

    # Dictionaries to store positions of odd and even numbers
    odd_positions = defaultdict(list)
    even_positions = defaultdict(list)

    # Populate the dictionaries with positions of odd and even numbers
    for i in range(n):
        if a[i] % 2 == 0:
            even_positions[a[i]].append(i)
        else:
            odd_positions[a[i]].append(i)

    # Function to perform BFS to find the minimum moves
    def bfs(start, target_set):
        queue = deque([(start, 0)])
        visited = set([start])

        while queue:
            current, steps = queue.popleft()
            if a[current] in target_set:
                return steps

            next_positions = [current - a[current], current + a[current]]
            for next_pos in next_positions:
                if 0 <= next_pos < n and next_pos not in visited:
                    visited.add(next_pos)
                    queue.append((next_pos, steps + 1))

        return float('inf')

    # For each position, calculate the minimum moves to reach the opposite parity
    for i in range(n):
        if a[i] % 2 == 0:
            result[i] = bfs(i, odd_positions.keys())
        else:
            result[i] = bfs(i, even_positions.keys())

    # Convert infinite values to -1
    for j in range(n):
        if result[j] == float('inf'):
            result[j] = -1

    return result

