import sys

def min_moves_to_opposite_parity(n, a):
    result = [-1] * n
    queue = deque()

    # Separate positions into odd and even parity
    odd_positions = []
    even_positions = []
    for i in range(n):
        if a[i] % 2 == 0:
            even_positions.append(i)
        else:
            odd_positions.append(i)

    # BFS from all odd positions to find the nearest even position
    for start in odd_positions:
        visited = set()
        queue.append((start, 0))
        while queue:
            current, steps = queue.popleft()
            if current in visited:
                continue
            visited.add(current)
            if current + a[current] < n and current + a[current] not in visited:
                queue.append((current + a[current], steps + 1))
            if current - a[current] >= 0 and current - a[current] not in visited:
                queue.append((current - a[current], steps + 1))
            if a[current] % 2 == 0:
                result[start] = steps
                break

    # Reset visited and queue for BFS from all even positions to find the nearest odd position
    visited = set()
    queue.clear()
    for start in even_positions:
        visited = set()
        queue.append((start, 0))
        while queue:
            current, steps = queue.popleft()
            if current in visited:
                continue
            visited.add(current)
