import queue

def min_moves_to_opposite_parity(n, a):
    ans = [-1] * n
    pq_odd = queue.Queue()
    pq_even = queue.Queue()

    for i in range(n):
        if a[i] % 2 == 0:
            pq_even.put((i, 0))
        else:
            pq_odd.put((i, 0))

    visited = [False] * n

    while not pq_odd.empty() or not pq_even.empty():
        if not pq_odd.empty():
            i, dist = pq_odd.get()
            if not visited[i]:
                visited[i] = True
                for j in [i - a[i], i + a[i]]:
                    if 0 <= j < n and not visited[j]:
                        ans[j] = dist + 1
                        if a[j] % 2 == 1:
                            pq_even.put((j, dist + 1))
        elif not pq_even.empty():
            i, dist = pq_even.get()
            if not visited[i]:
                visited[i] = True
                for j in [i - a[i], i + a[i]]:
                    if 0 <= j < n and not visited[j]:
                        ans[j] = dist + 1
                        if a[j] % 2 == 0:
                            pq_odd.put((j, dist + 1))

    return ans

